class SharedCache<K,V> {
    Map<K,V> mapa = new HashMap<>();
    Object lock = new Object();
    synchronized V get(K k) { synchronized(lock) { return mapa.get(k); } }
    void computeIfAbsent(K k, java.util.function.Function<K,V> f) {
        synchronized(lock) { if (mapa.containsKey(k)) return; }
        V wartosc = f.apply(k); // POZA lockiem - moze byc kosztowne (np. sleep)
        synchronized(lock) { mapa.putIfAbsent(k, wartosc); }
    }
}

